/*
 * A089996  a(n) = primes generated by the function (
 *          f[n_]=Floor[(A004001[n]*Prime[n])*Log[2]/(2*PrimePi[n]+1)]).
 * https://oeis.org/A089996
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th smallest distinct prime among f(k) =
 *            floor(A004001(k)*prime(k)*log(2)/(2*pi(k)+1)), k >= 1 (computed
 *            by sieve: tabulate f(k) for k up to a bound, sort, keep distinct
 *            primes; the bound is enlarged until a proven lower bound on f(k)
 *            for larger k exceeds the answer)
 * Range:     u8 n <= 13, u16 n <= 50, u32 n <= 50, u64 n <= 50, u128 n <= 50,
 *            big any n
 * Validated: partial, pass, 50 terms through n = 50 (2026-11-07)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

static uint64_t *A089996_res = NULL;
static uint64_t A089996_cnt = 0;
static uint64_t A089996_S = 0;
static uint64_t A089996_N = 0;

static bool A089996_isprime(uint64_t x) {
  if (x < 2) return false;
  if (x % 2 == 0) return x == 2;
  for (uint64_t d = 3; d * d <= x; d += 2)
    if (x % d == 0) return false;
  return true;
}

static int A089996_cmp(const void *p, const void *q) {
  uint64_t x = *(const uint64_t *)p, y = *(const uint64_t *)q;
  return (x > y) - (x < y);
}

/* lower bound for f(k), k >= 2: A004001(k) >= k/2, prime(k) > k ln k, pi(k) < 1.25506 k/ln k */
static double A089996_lower(uint64_t k) {
  double kk = (double)k, lk = log(kk);
  return (kk / 2.0) * (kk * lk) * 0.6931471805599453 / (2.0 * 1.25506 * kk / lk + 1.0) - 2.0;
}

static void A089996_build(uint64_t S) {
  unsigned char *comp = (unsigned char *)calloc(S + 1, 1);
  uint32_t *primes = (uint32_t *)malloc(sizeof(uint32_t) * (S / 2 + 10));
  uint64_t np = 0;
  for (uint64_t i = 2; i <= S; i++) {
    if (!comp[i]) {
      primes[np++] = (uint32_t)i;
      for (uint64_t j = i * i; j <= S; j += i) comp[j] = 1;
    }
  }
  uint64_t N = np;
  uint32_t *con = (uint32_t *)calloc(N + 3, sizeof(uint32_t));
  con[1] = 1; con[2] = 1;
  for (uint64_t i = 3; i <= N; i++) con[i] = con[con[i - 1]] + con[i - con[i - 1]];

  const unsigned __int128 LN2 = (unsigned __int128)693147180559945309ULL;
  const unsigned __int128 SCALE = (unsigned __int128)1000000000000000000ULL;

  uint64_t *fv = (uint64_t *)malloc(sizeof(uint64_t) * (N + 1));
  uint64_t pi = 0;
  for (uint64_t k = 1; k <= N; k++) {
    if (k >= 2 && !comp[k]) pi++;
    unsigned __int128 num = (unsigned __int128)((uint64_t)con[k] * (uint64_t)primes[k - 1]) * LN2;
    unsigned __int128 den = (unsigned __int128)(2 * pi + 1) * SCALE;
    fv[k - 1] = (uint64_t)(num / den);
  }
  qsort(fv, N, sizeof(uint64_t), A089996_cmp);

  free(A089996_res);
  A089996_res = (uint64_t *)malloc(sizeof(uint64_t) * (N + 1));
  A089996_cnt = 0;
  for (uint64_t i = 0; i < N; i++) {
    if (i > 0 && fv[i] == fv[i - 1]) continue;
    if (A089996_isprime(fv[i])) A089996_res[A089996_cnt++] = fv[i];
  }
  free(fv); free(comp); free(primes); free(con);
  A089996_S = S;
  A089996_N = N;
}

seq_t a(idx_t n) {
  if (n < 1) return 0;
  if (A089996_S == 0) A089996_build(1u << 14);
  for (;;) {
    if (A089996_cnt >= (uint64_t)n) {
      uint64_t v = A089996_res[n - 1];
      if (A089996_lower(A089996_N + 1) > (double)v) return (seq_t)v;
    }
    A089996_build(A089996_S * 2);
  }
}
